exercise.solution:
fn route(method: &str, path: &str) -> String {
    let segs: Vec<&str> = path.split('/').filter(|s| !s.is_empty()).collect();
    match (method, segs.as_slice()) {
        ("GET", ["health"]) => "health_handler".into(),
        ("GET", ["orders", id]) if id.parse::<u64>().is_ok() => "order_by_id".into(),
        ("POST", ["orders"]) => "create_order".into(),
        _ => "404 not found".into(),
    }
}

fn main() {
    println!("{}", route("GET", "/health"));
    println!("{}", route("GET", "/orders/42"));
    println!("{}", route("POST", "/orders"));
    println!("{}", route("GET", "/nope"));
}
